&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Responsibilities and Duties&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
