&lt;li style=&quot;margin-top: 0px; margin-bottom: 0px; vertical-align: middle; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;; font-size: 12.0pt;&quot;&gt;Support care delivery through in-home visits as needed&lt;/span&gt;&lt;/li&gt;
